// devrt notify.send stub fixture (tests/devrt/sandbox.test.js)

function settle(p) {
  return p.then(function (r) { return { resolved: r }; },
    function (e) { return { rejected: e.message, name: e.name, isError: e instanceof Error }; });
}

// Argument / field shapes that JSON cannot express. jscases.json holds what the host does with each one
// (generated by running this file in the real host runtime): "TypeError: <message>" = thrown synchronously,
// "resolved" / "rejected: <reason>" = the returned Promise.
function btn(extra) { var b = { label: "a", url: "https://a.example/" }; for (var k in extra) b[k] = extra[k]; return b; }
function act(extra) { var b = { label: "a", action: "retry" }; for (var k in extra) b[k] = extra[k]; return b; }
function cyclic() { var o = {}; o.self = o; return o; }
var jsCases = {
  "": function () { return notify.send(); },
  "undefined": function () { return notify.send(undefined); },
  "null": function () { return notify.send(null); },
  "string": function () { return notify.send("title"); },
  "number": function () { return notify.send(42); },
  "function": function () { return notify.send(function () {}); },
  "array": function () { return notify.send([{ title: "x" }]); },
  "String object as message": function () { return notify.send(new String("x")); },
  "Date as message": function () { return notify.send(new Date(0)); },
  "title number": function () { return notify.send({ title: 1 }); },
  "title object": function () { return notify.send({ title: {} }); },
  "title function": function () { return notify.send({ title: function () {} }); },
  "body number": function () { return notify.send({ title: "t", body: 2 }); },
  "image array": function () { return notify.send({ title: "t", image: [] }); },
  "title cyclic": function () { return notify.send({ title: cyclic() }); },
  "title bigint": function () { return notify.send({ title: BigInt(1) }); },
  "title String object": function () { return notify.send({ title: new String("t") }); },
  "title toJSON object": function () { return notify.send({ title: { toJSON: function () { return "t"; } } }); },
  "body String object": function () { return notify.send({ title: "t", body: new String("b") }); },
  "body toJSON object": function () { return notify.send({ title: "t", body: { toJSON: function () { return "b"; } } }); },
  "image String object": function () { return notify.send({ title: "t", image: new String("https://a.example/p.png") }); },
  "title getter": function () { return notify.send({ get title() { return "t"; } }); },
  "title undefined body null": function () { return notify.send({ title: "t", body: null, image: undefined }); },
  "buttons string": function () { return notify.send({ title: "t", buttons: "x" }); },
  "buttons object": function () { return notify.send({ title: "t", buttons: {} }); },
  "buttons toJSON object": function () { return notify.send({ title: "t", buttons: { toJSON: function () { return []; } } }); },
  "buttons array toJSON ignored": function () {
    var a = [btn({ url: "javascript:x" })];
    a.toJSON = function () { return []; };
    return notify.send({ title: "t", buttons: a });
  },
  "button toJSON ignored": function () { return notify.send({ title: "t", buttons: [btn({ toJSON: function () { return { label: "" }; } })] }); },
  "buttons length over 1000000": function () { var a = []; a.length = 1000001; return notify.send({ title: "t", buttons: a }); },
  "rows then flat": function () { return notify.send({ title: "t", buttons: [[btn()], btn()] }); },
  "flat then row": function () { return notify.send({ title: "t", buttons: [btn(), [btn()]] }); },
  "row not array": function () { return notify.send({ title: "t", buttons: [[btn()], "x"] }); },
  "array inside a row is a button object": function () { return notify.send({ title: "t", buttons: [[[]]] }); },
  "hole first": function () { var a = [, btn()]; return notify.send({ title: "t", buttons: a }); },
  "button number": function () { return notify.send({ title: "t", buttons: [1] }); },
  "row button number": function () { return notify.send({ title: "t", buttons: [[1]] }); },
  "button function": function () { return notify.send({ title: "t", buttons: [function () {}] }); },
  "button Date": function () { return notify.send({ title: "t", buttons: [new Date(0)] }); },
  "label number": function () { return notify.send({ title: "t", buttons: [{ label: 2, url: "u" }] }); },
  "url number": function () { return notify.send({ title: "t", buttons: [{ label: "a", url: 3 }] }); },
  "action boolean": function () { return notify.send({ title: "t", buttons: [{ label: "a", action: true }] }); },
  "label String object": function () { return notify.send({ title: "t", buttons: [btn({ label: new String("a") })] }); },
  "url toJSON object": function () { return notify.send({ title: "t", buttons: [{ label: "a", url: { toJSON: function () { return "https://a.example/"; } } }] }); },
  "action String object": function () { return notify.send({ title: "t", buttons: [{ label: "a", action: new String("retry") }] }); },
  "label getter": function () { return notify.send({ title: "t", buttons: [{ get label() { return "a"; }, url: "https://a.example/" }] }); },
  "data function = no data": function () { return notify.send({ title: "t", buttons: [act({ data: function () {} })] }); },
  "data function on link = no data": function () { return notify.send({ title: "t", buttons: [btn({ data: function () {} })] }); },
  "data cyclic": function () { return notify.send({ title: "t", buttons: [act({ data: cyclic() })] }); },
  "data bigint": function () { return notify.send({ title: "t", buttons: [act({ data: BigInt(1) })] }); },
  "data toJSON big": function () { return notify.send({ title: "t", buttons: [act({ data: { toJSON: function () { return "x".repeat(5000); } } })] }); },
  "data toJSON undefined = no data": function () { return notify.send({ title: "t", buttons: [btn({ data: { toJSON: function () { return undefined; } } })] }); },
  "data html chars not escaped": function () { return notify.send({ title: "t", buttons: [act({ data: "<".repeat(4094) })] }); },
  "data html chars one over": function () { return notify.send({ title: "t", buttons: [act({ data: "<".repeat(4095) })] }); },
  "data U+2028 escaped": function () { return notify.send({ title: "t", buttons: [act({ data: "\u2028".repeat(682) })] }); },
  "data U+2028 escaped over": function () { return notify.send({ title: "t", buttons: [act({ data: "\u2028".repeat(683) })] }); },
  "data keys sorted size": function () { return notify.send({ title: "t", buttons: [act({ data: { b: "x".repeat(4080), a: 1 } })] }); },
  "undeclared action thrown before content": function () { return notify.send({ title: "", buttons: [{ label: "", action: "nope" }] }); },
  "declared action": function () { return notify.send({ title: "t", buttons: [act({ data: { n: 1 } })] }); },
};

plugin.registerAPI("/jscases", async function () {
  var out = {};
  var keys = Object.keys(jsCases);
  for (var i = 0; i < keys.length; i++) {
    var p;
    try {
      p = jsCases[keys[i]]();
    } catch (e) {
      out[keys[i]] = (e instanceof TypeError ? "TypeError: " : "other: ") + e.message;
      continue;
    }
    try {
      await p;
      out[keys[i]] = "resolved";
    } catch (e) {
      out[keys[i]] = "rejected: " + e.message;
    }
  }
  return out;
});

// body: JSON array of messages → each one's outcome ("" = accepted, else the reject reason)
plugin.registerAPI("/vectors", async function (req) {
  var msgs = JSON.parse(req.body);
  var out = [];
  for (var i = 0; i < msgs.length; i++) {
    try {
      await notify.send(msgs[i]);
      out.push("");
    } catch (e) {
      out.push(e.message);
    }
  }
  return out;
});

plugin.registerAPI("/send", function (req) { return settle(notify.send(JSON.parse(req.body))); });

// The Promise is already settled when send returns: a reaction queued right away runs before a later microtask
plugin.registerAPI("/sync-settle", async function () {
  var seen = [];
  var a = notify.send({ title: "a" });
  var b = notify.send({ title: "" });
  var c = notify.send({ title: "c" });
  [a, b, c].forEach(function (p, i) { p.then(function () { seen.push(i + ":ok"); }, function () { seen.push(i + ":rej"); }); });
  await null;
  return seen;
});

// should_download: sending inside the veto hook (awaited or not, resolved or rejected) never changes its verdict
plugin.on("should_download", async function (p) {
  if (p.mode === "await-reject-veto") { try { await notify.send({ title: "" }); } catch (e) {} return false; }
  if (p.mode === "unawaited-reject-veto") { notify.send({ title: "" }); return false; }
  if (p.mode === "await-ok-allow") { await notify.send({ title: "t" }); return true; }
  return true;
});

// Interaction hooks (devrt console: trigger on_notify_action / on_bot_command)
plugin.on("on_notify_action", async function (p) {
  var mode = p.data && p.data.mode;
  if (mode === "throw") throw new Error("boom");
  if (mode === "hang") return new Promise(function () {});
  if (mode === "obj") return { text: "  第一行\r\n第二行  " };
  if (mode === "long") return "长".repeat(250);
  if (mode === "none") return undefined;
  if (mode === "number") return 42;
  if (mode === "send") { await notify.send({ title: "from action" }); return "sent"; }
  return "已" + p.action + "：" + JSON.stringify(p.data) + " by " + p.user.username + "/" + p.user.role + " via " + p.channel;
});
plugin.on("on_bot_command", function (p) {
  // "json <JSON>": return that value as the reply (reply-vectors.json)
  if (typeof p.args === "string" && p.args.indexOf("json ") === 0) return JSON.parse(p.args.slice(5));
  if (p.args === "md") return { body: "**加粗** [链接](https://a.example/)", buttons: [{ label: "重试", action: "retry", data: { n: 1 } }, { label: "打开", url: "https://a.example/" }] };
  if (p.args === "undeclared") return { body: "x", buttons: [{ label: "a", action: "nope" }] };
  if (p.args === "badlink") return { body: "[x](ftp://a.example/)" };
  if (p.args === "bodytype") return { body: 1 };
  if (p.args === "empty") return "";
  if (p.args === "emptyobj") return { body: " " };
  if (p.args === "number") return 7;
  if (p.args === "throw") throw new Error("boom");
  return "收到 /" + p.command + " " + p.args + "（" + p.user.username + "，chat " + p.chat.id + " " + p.chat.type + "）**不解析**";
});
